import {balancedSpin} from './MathPolicy';
import {boostBase} from './BasePayoutBoost';
import {scalePayout,payoutScale} from './PayoutPolicy';
import {SlotMain,SpinResult} from './SlotMain';
/** Base-game hit means any positive payout before free spins (including base cascades).
 * Fixed, account-independent distribution. No loss history, wallet or purchase inputs.
 * Evaluated boards/features are retained; PayoutPolicy applies the calibrated payout scale.
 */
export const baselineHitRates:Record<string,number>={animal:.4466,cherry:.49885,clockwork:.28425,'animal-lines':.13905,'puppy-sky':.33815,'space-scrap':.36695,'mushroom-rush':.4416,'pirate-stars':.33405,'pizza-courier':.117,'fruit-house':.1855,'robot-duel':.27145,'cat-mine':.2083,'coral-post':.31595,'neon-greenhouse':.41245,'cookie-lab':.6084,'desert-express':.3235,'robot-factory':.4947,'windup-workshop':.6079,'paper-library':.21725,'sushi-party':.5198};
export const TARGET_BASE_HIT=.40;
export const isBaseHit=(r:SpinResult)=>(r.rounds?.[0]||r).payout>0;
const samplers=new WeakMap<SlotMain,(bet:number,rng:()=>number)=>SpinResult>();
export function unscaledSpin(slot:SlotMain,bet:number,rng:()=>number){return samplers.get(slot)!(bet,rng);}
export function applyHitRatePolicy(slot:SlotMain):SlotMain{
 const raw=slot.spin.bind(slot),baseline=baselineHitRates[slot.config.id];
 if(baseline===undefined)throw Error('Missing hit-rate calibration: '+slot.config.id);
 const rescue=Math.max(0,(TARGET_BASE_HIT-baseline)/(1-baseline));
 const sample=(bet:number,rng:()=>number)=>{
  const first=raw(bet,rng);if(isBaseHit(first)||rescue===0||rng()>=rescue)return first;
  // Select only fully evaluated legal outcomes. Bound pathological deterministic RNGs.
  for(let attempt=0;attempt<256;attempt++){const next=raw(bet,rng);if(isBaseHit(next))return next;}
  return first;
 };
 samplers.set(slot,sample);
 slot.spin=(bet:number,rng:()=>number=Math.random)=>balancedSpin(slot,bet,rng,()=>boostBase(slot,scalePayout(sample(bet,rng),payoutScale(slot,bet),rng),rng));
 return slot;
}
