import {Node,UITransform,UIOpacity,Graphics,Color,Label,Font,Vec3,tween,Tween} from 'cc';
import {avatar} from './PixelArt';
import {Costume,Profile,ticketText} from '../services/PlayerStore';
import {PerkAward,costumePerks} from '../services/CostumePerks';
/** One line per activation, chronological rows, newest at the bottom. */
export class PerkToasts {
 private root:Node;private cards:Node[]=[];private queue:{item:Costume;award:PerkAward}[]=[];private pumping=false;private timer={value:0};private closing=false;private closeResolve:(()=>void)|null=null;
 constructor(parent:Node,private width:number,private height:number,private hudTop:number,private font:Font|null,private profile:Profile|null){this.root=new Node('Costume activation stack');this.root.layer=parent.layer;parent.addChild(this.root);}
 add(item:Costume,award:PerkAward){
  if(this.closing)return;this.queue.push({item,award});Tween.stopAllByTarget(this.timer);
  for(const card of this.cards){const opacity=card.getComponent(UIOpacity)!;Tween.stopAllByTarget(opacity);opacity.opacity=255;}
  if(!this.pumping)this.pump();
 }
 private pump(){
  const entry=this.queue.shift();if(!entry){this.pumping=false;this.expire();return;}
  this.pumping=true;this.show(entry.item,entry.award);
  tween(this.root).delay(.1).call(()=>this.pump()).start();
 }
 private show(item:Costume,award:PerkAward){
  const w=Math.min(this.width-48,740),card=new Node('Costume perk '+item.id);card.layer=this.root.layer;this.root.addChild(card);card.addComponent(UITransform).setContentSize(w,64);const base=this.height/2-this.hudTop+42;card.setPosition(0,base-72);const g=card.addComponent(Graphics);g.fillColor=new Color(['#193b42','#393052','#493044','#354124','#493b25','#263851'][Array.from(item.id).reduce((n,c)=>n+c.charCodeAt(0),0)%6]);g.rect(-w/2,-32,w,64);g.fill();g.strokeColor=new Color(item.color);g.lineWidth=2;g.rect(-w/2+1,-31,w-2,62);g.stroke();
  const art=new Node('Activated costume art');art.layer=card.layer;card.addChild(art);art.setPosition(-w/2+30,0);avatar(art.addComponent(Graphics),0,0,3,item.color,this.profile?.skin,this.profile?.gender,item.id,{[item.slot]:item.id},this.profile?.appearance,item.slot);
  const n=new Node('Perk activation line');n.layer=card.layer;card.addChild(n);n.addComponent(UITransform).setContentSize(w-76,34);n.setPosition(28,0);const l=n.addComponent(Label);if(this.font)l.font=this.font;l.fontSize=26;l.lineHeight=34;l.color=new Color('#fff0cb');l.horizontalAlign=Label.HorizontalAlign.LEFT;l.verticalAlign=Label.VerticalAlign.CENTER;l.enableWrapText=false;l.overflow=Label.Overflow.CLAMP;
  const perk=costumePerks[item.id],reward=perk?(perk.currency==='coins'?'코인':'티켓')+' +'+(perk.bps/100)+'%':'효과 발동';l.string=award.condition+' · '+reward;n.getComponent(UITransform)!.setContentSize(w-76,42);
  const opacity=card.addComponent(UIOpacity);opacity.opacity=0;tween(opacity).to(.09,{opacity:255}).start();this.cards.push(card);
  this.cards.forEach((row,i)=>{Tween.stopAllByTarget(row);tween(row).to(.09,{position:new Vec3(0,base+(this.cards.length-1-i)*72,0)},{easing:'quadOut'}).start();});

 }
 private expire(){
  // Last push completes in .09s; pump reaches here .10s after it began.
  tween(this.timer).delay(.99).call(()=>{
   for(const card of this.cards){const opacity=card.getComponent(UIOpacity)!;Tween.stopAllByTarget(opacity);tween(opacity).to(.18,{opacity:0}).start();}
  }).delay(.18).call(()=>{for(const card of this.cards)card.destroy();this.cards=[];if(this.closing)this.finish();}).start();
 }
 bringToFront(){if(this.root.isValid&&this.root.parent)this.root.setSiblingIndex(this.root.parent.children.length-1);}
 private finish(){Tween.stopAllByTarget(this.timer);Tween.stopAllByTarget(this.root);this.root.removeFromParent();this.root.destroy();this.closeResolve?.();this.closeResolve=null;}
 async close(){this.closing=true;if(!this.cards.length&&!this.queue.length){this.finish();return;}await new Promise<void>(resolve=>{this.closeResolve=resolve;});}
}
