import {Node,Graphics,Color,UITransform} from 'cc';
export function themedBackdrop(parent:Node,layer:number,width:number,height:number,id:string):void{
 if(id==='animal'){forestBackdrop(parent,layer,width,height);return;}
 const node=new Node('Theme backdrop '+id);node.layer=layer;parent.addChild(node);const g=node.addComponent(Graphics);
 const rect=(x:number,y:number,w:number,h:number,color:string)=>{g.fillColor=new Color(color);g.rect(x,height-y-h,w,h);g.fill();};
 if(id==='paper-library'){
  rect(0,0,width,height,'#39384f');for(let y=120;y<height;y+=115){rect(0,y+70,width,12,'#aa805c');for(let x=0;x<width;x+=32)rect(x,y+(x%3)*4,23,65-(x%3)*4,['#b88eaa','#8aada3','#c6af78'][Math.floor(x/32)%3]);}
 }else if(id==='sushi-party'){
  rect(0,0,width,height,'#355a60');for(let x=28;x<width;x+=135){rect(x,0,3,120,'#b99471');rect(x-19,100,42,55,'#e3a186');rect(x-13,108,30,38,'#f5cd9a');}rect(0,height-115,width,115,'#a67c5d');for(let x=0;x<width;x+=65){rect(x,height-100,50,10,'#efdbc1');rect(x+12,height-115,26,16,'#df9a8c');}
 }else if(id==='cat-mine'){
  rect(0,0,width,height,'#38333f');rect(0,height*.72,width,height*.28,'#725844');for(let c=0;c<width/110;c++){rect(c*110,90,14,height,'#98764f');rect(c*110,110,110,14,'#98764f');for(let i=0;i<4;i++){rect(c*110+38,180+i*150,24,16,i%2?'#eac268':'#7d718e');rect(c*110+44,172+i*150,12,30,i%2?'#eac268':'#7d718e');}}rect(0,height-82,width,5,'#bbb4a5');rect(0,height-48,width,5,'#bbb4a5');
 }else if(id==='coral-post'){
  rect(0,0,width,height,'#315c70');rect(0,height*.7,width,height*.3,'#4c8290');for(let i=0;i<25;i++){const x=(i*137)%width,y=116+(i*83)%(height-150);rect(x,y,10,4,'#98c8cf');rect(x-4,y+4,4,12,'#98c8cf');rect(x+10,y+4,4,12,'#98c8cf');rect(x,y+16,10,4,'#98c8cf');}for(let c=0;c<width/70;c++){rect(c*70,height-90,10,90,'#db9eae');rect(c*70-14,height-64,40,8,'#db9eae');}
 }else if(id==='neon-greenhouse'){
  rect(0,0,width,height,'#203e41');for(let c=0;c<width/100;c++){rect(c*100,94,4,height,'#97c4af');for(let row=0;row<5;row++)rect(c*100,96+row*height/5,100,4,'#799f96');}for(let c=0;c<width/72;c++){rect(c*72,height-88,45,30,'#b67993');rect(c*72+20,height-144,6,60,'#9ac575');rect(c*72+7,height-150,34,18,c%2?'#e4b668':'#d09cdc');}
 }else if(id==='cookie-lab'){
  rect(0,0,width,height,'#74554f');rect(0,height*.7,width,height*.3,'#b18c72');for(let c=0;c<width/100;c++){rect(c*100,102,50,28,'#e6bcad');rect(c*100+16,height-100,60,40,'#694f4f');rect(c*100+25,height-90,42,16,'#e9ab63');}for(let row=0;row<4;row++)rect(0,180+row*150,width,6,'#9d7661');
 }else if(id==='desert-express'){
  rect(0,0,width,height,'#8eacaf');rect(width-150,112,65,65,'#eed195');for(let c=0;c<width/90;c++){rect(c*90,height*.53+(c%3)*22,100,height,'#bc9672');rect(c*90,height*.72+(c%2)*20,100,height,'#d2b18a');}rect(0,height-82,width,7,'#665345');rect(0,height-52,width,7,'#665345');for(let c=0;c<width/44;c++)rect(c*44,height-95,12,66,'#927357');
 }else if(id==='robot-factory'){
  rect(0,0,width,height,'#2d465b');for(let c=0;c<width/120;c++){rect(c*120,96,18,height,'#557a89');for(let row=0;row<5;row++){rect(c*120+30,122+row*130,54,22,'#203446');rect(c*120+36,128+row*130,12,8,row%2?'#d0c179':'#90c9b4');}}rect(0,height-90,width,60,'#627b86');for(let c=0;c<width/40;c++)rect(c*40,height-74,24,28,'#314552');
 }else if(id==='windup-workshop'){
  rect(0,0,width,height,'#524659');rect(0,height*.7,width,height*.3,'#947766');for(let row=0;row<4;row++){const y=150+row*150;rect(0,y,width,8,'#ba986e');for(let c=0;c<width/85;c++){rect(c*85+12,y-48,42,42,(c+row)%2?'#a9c1b0':'#cb98a4');rect(c*85+26,y-64,14,16,'#dbc294');}}rect(0,height-80,width,14,'#e1be83');
 }else if(id==='puppy-sky'){
  rect(0,0,width,height,'#283c64');rect(0,height*.56,width,height*.44,'#455a83');rect(width-166,128,78,78,'#f7d695');
  for(let i=0;i<12;i++){const x=(i*177)%width,y=130+(i*137)%Math.max(1,height-250);rect(x,y,96,16,'#738bb1');rect(x+18,y-14,60,18,'#879cbb');rect(x+32,y-24,28,12,'#a7b7ce');}
 }else if(id==='space-scrap'){
  rect(0,0,width,height,'#1c2942');rect(0,height*.8,width,height*.2,'#30435a');for(let i=0;i<65;i++)rect((i*137)%width,110+(i*193)%Math.max(1,height-120),i%4?3:7,i%4?3:7,i%2?'#79b4b1':'#e3c99b');for(let i=0;i<8;i++){rect(i*width/8,height-80,4,80,'#769990');rect(i*width/8,height-80,40,4,'#769990');}
 }else if(id==='mushroom-rush'){
  rect(0,0,width,height,'#493c50');rect(0,height*.65,width,height*.35,'#5d6350');for(let i=0;i<10;i++){const x=i%2?width-85:15,y=100+Math.floor(i/2)*height/5;rect(x+23,y+28,12,62,'#d4bca4');rect(x,y,64,32,i%3?'#bc727e':'#caab78');rect(x+12,y-12,40,15,i%3?'#bc727e':'#caab78');rect(x+10,y+7,12,8,'#f3dbc8');}}
 else if(id==='pirate-stars'){
  rect(0,0,width,height,'#263d54');rect(0,height*.60,width,height*.4,'#2f626f');rect(width-168,125,72,72,'#e4cda0');for(let row=0;row<8;row++)for(let col=0;col<width/90;col++)rect(col*90+(row%2)*35,height*.62+row*38,42,5,row%2?'#72a8ac':'#4b8b98');for(let i=0;i<35;i++)rect((i*137)%width,105+(i*73)%Math.max(1,height*.5),3,3,'#e7c98a');
 }else if(id==='animal-lines'){
  rect(0,0,width,height,'#263747');rect(0,110,width,height*.42,'#4b7275');rect(0,height*.6,width,height*.4,'#315655');rect(width-185,135,74,74,'#f2d99b');
  for(let i=0;i<width/80;i++){rect(i*80,height*.62-((i*7)%4)*12,84,54,'#4c8072');rect(i*80+22,height*.68,6,35,'#98bb8b');rect(i*80+12,height*.68-8,26,12,i%2?'#d69aae':'#ddc581');}
  for(let i=0;i<10;i++)rect((i*151)%width,height*.82+(i%3)*12,52,4,'#639291');
 }else if(id==='clockwork'){
  rect(0,0,width,height,'#252435');rect(0,height*.7,width,height*.3,'#4c3438');
  for(let side=0;side<2;side++)for(let i=0;i<7;i++){const x=side?width-24-i*15:i*15;rect(x,90,16,height*.68-i*17,i%2?'#694051':'#533145');rect(x,height*.73-i*17,16,8,'#d9a16b');}
  for(let i=0;i<width/72;i++){rect(i*72,104,48,10,'#b5835e');rect(i*72+16,height-188,8,15,'#edb76e');}
 }else if(id==='robot-duel'){
  rect(0,0,width,height,'#1e3046');rect(0,height*.65,width,height*.35,'#314c63');for(let side=0;side<2;side++){const x=side?width-60:12;rect(x,120,36,height-200,'#496479');for(let i=0;i<8;i++){rect(x+8,150+i*100,20,12,i%2?'#e9ad64':'#80d6dc');rect(x-8,160+i*100,52,4,'#6f91a1');}}for(let i=0;i<width/48;i++)rect(i*48,height-80,24,6,'#edb568');
 }else if(id==='pizza-courier'){
  rect(0,0,width,height,'#613731');rect(0,height*.67,width,height*.33,'#815444');for(let i=0;i<width/52;i++)rect(i*52,106,26,40,i%2?'#f4d195':'#b64748');
  for(let side=0;side<2;side++){const x=side?width-86:8;rect(x,190,72,94,'#b16942');rect(x+8,206,56,48,'#392e35');rect(x+22,228,12,22,'#ee9851');rect(x+38,220,10,30,'#f8d17a');}for(let i=0;i<width/60;i++)rect(i*60,height-100,30,22,'#e6bd8b');
 }else if(id==='fruit-house'){
  rect(0,0,width,height,'#314f48');rect(0,height*.62,width,height*.38,'#6b8056');for(let side=0;side<2;side++)for(let i=0;i<4;i++){const x=side?width-78:8,y=160+i*170;rect(x+28,y+32,14,110,'#846148');rect(x,y,72,68,'#67834e');rect(x+12,y-16,44,40,'#86a65c');rect(x+12,y+24,14,14,'#e5a264');rect(x+47,y+8,14,14,'#d9756c');}for(let i=0;i<width/54;i++){rect(i*54,height-88,8,70,'#d7bc83');rect(i*54,height-68,54,8,'#d7bc83');}
 }else if(id==='moon'){
  rect(0,0,width,height,'#211d46');rect(0,height*.65,width,height*.35,'#34275d');
  for(let i=0;i<75;i++){const x=(i*173+21)%width,y=(i*97+100)%height;rect(x,y,3+i%3,3+i%3,i%3?'#7779bd':'#f7d998');}
  rect(width-190,160,96,96,'#ffe8af');rect(width-164,148,80,80,'#211d46');
  for(let i=0;i<24;i++)rect(i*width/24,height-40-(i*19%70),width/28,100,'#514178');
 }else if(id==='cherry'){
  rect(0,0,width,height,'#94b8bd');rect(0,height*.62,width,height*.38,'#75966b');
  for(let i=0;i<5;i++){const x=i*width/4-40,y=160+(i%2)*48;rect(x,y,100,16,'#d8e2ca');rect(x+20,y-16,56,20,'#d8e2ca');}
  for(let i=0;i<width/60;i++){rect(i*60,height*.7,8,height*.3,'#e2c9a2');rect(i*60,height*.73,60,8,'#e2c9a2');}
  rect(0,height-64,width,64,'#62855d');for(let i=0;i<width/32;i++)rect(i*32,height-40+(i%3)*8,12,4,'#a5b97a');
 }else if(id==='garden'){
  rect(0,0,width,height,'#244f51');rect(0,height*.4,width,height*.6,'#347161');
  for(let i=0;i<width/140;i++){rect(i*140,95,6,height,'#559a80');rect(i*140+12,112,110,8,'#8ac9a4');}
  rect(0,height-90,width,90,'#a77c53');
  for(let i=0;i<width/65;i++){const x=i*65;rect(x,height-85,42,38,'#d59974');rect(x+18,height-125,6,42,'#a6d47a');rect(x+5,height-131,30,12,i%2?'#ffb4c5':'#ffda82');rect(x+14,height-140,12,30,i%2?'#ffb4c5':'#ffda82');}
 }else{
  rect(0,0,width,height,'#252443');
  const colors=['#4b3b70','#245b69','#704353','#425e52'];
  for(let i=0;i<20;i++){const x=(i*193)%width,y=110+(i*139)%Math.max(1,height-140);rect(x,y,40+(i%3)*20,12,colors[i%4]);rect(x+12,y-12,12,36,colors[i%4]);}
 }
}
/** Lightweight, static pixel scenery. Dense decoration stays outside the reels. */
export function forestBackdrop(parent:Node,layer:number,width:number,height:number):void{
 const node=new Node('Pixel forest backdrop');node.layer=layer;parent.addChild(node);node.addComponent(UITransform).setContentSize(width,height);const g=node.addComponent(Graphics);
 function rect(x:number,y:number,w:number,h:number,color:string){g.fillColor=new Color(color);g.rect(Math.round(x),Math.round(height-y-h),Math.ceil(w),Math.ceil(h));g.fill();}
 rect(0,0,width,height,'#233c43');rect(0,0,width,height*.25,'#242f43');rect(0,height*.25,width,height*.28,'#263e48');rect(0,height*.7,width,height*.3,'#29443e');
 // Layered stepped silhouettes, rather than a smooth high-resolution gradient.
 for(let i=0;i<Math.ceil(width/32);i++){const x=i*32,y=height*.27+((i*17)%5)*8;rect(x,y,32,height*.17,'#293f48');}
 function tree(x:number,y:number,s:number,shade:string){rect(x-4*s,y,8*s,130*s,'#263c3a');rect(x-26*s,y-35*s,52*s,44*s,shade);rect(x-38*s,y-15*s,76*s,42*s,shade);rect(x-22*s,y-49*s,44*s,26*s,shade);rect(x-29*s,y-28*s,16*s,8*s,'#3f6052');}
 for(let i=0;i<4;i++){tree(14+i*15,height*.24+i*height*.18,.8+(i%2)*.25,i%2?'#345449':'#304b45');tree(width-16-i*14,height*.31+i*height*.16,.8+(i%2)*.3,i%2?'#345449':'#304b45');}
 for(let i=0;i<46;i++){const side=i%2,x=side?width-12-(i*37)%74:12+(i*29)%74,y=108+(i*97)%Math.max(1,height-150);rect(x,y,3,3,i%4?'#587360':'#c3ac65');if(i%7===0){rect(x-3,y+1,9,2,'#89996a');rect(x+1,y-3,2,9,'#89996a');}}
 for(let i=0;i<Math.ceil(width/24);i++){const x=i*24,y=height-10-(i%3)*7;rect(x,y,24,40,'#1a302f');rect(x+8,y-8,8,14,'#314e40');}
}
