import {Node,Graphics,Color,UITransform,UIOpacity,Label,Font,BlockInputEvents,Vec3,tween} from 'cc';
import {uiIcon} from './UIIcons';
/** Shared, centered entry/exit presentation. Never mutates the wallet or autoplay. */
export class FreeSpinPopup {
 readonly root:Node;
 constructor(parent:Node,width:number,height:number,contentWidth:number,font:Font|null,mode:'entry'|'exit',count:number,payout:number,title:string,onContinue:()=>void){
  const root=this.root=new Node('Free spins '+mode);root.layer=parent.layer;parent.addChild(root);
  const node=(name:string,x:number,y:number,w:number,h:number)=>{const n=new Node(name);n.layer=root.layer;root.addChild(n);n.setPosition(x,y);n.addComponent(UITransform).setContentSize(w,h);return n;};
  const rect=(name:string,x:number,y:number,w:number,h:number,color:string)=>{const n=node(name,x,y,w,h),g=n.addComponent(Graphics);g.fillColor=new Color(color);g.rect(-w/2,-h/2,w,h);g.fill();return n;};
  const shade=rect('Free spins backdrop',0,0,width,height,'#111322');shade.addComponent(UIOpacity).opacity=100;shade.addComponent(BlockInputEvents);shade.on(Node.EventType.TOUCH_END,(event:any)=>{event.propagationStopped=true;onContinue();});
  const w=Math.min(contentWidth-96,620),h=Math.min(height*.64,440),accent=mode==='entry'?'#b2eee0':'#ffe094';
  rect('Frame shadow',7,-9,w+10,h+10,'#111220');rect('Gold frame',0,0,w,h,accent);const panel=rect('Free spins plaque',0,0,w-8,h-8,'#302c4b');
  const label=(name:string,value:string,y:number,size:number,color:string)=>{const n=node(name,0,y,w-42,size*1.5),l=n.addComponent(Label);if(font)l.font=font;l.string=value;l.fontSize=size;l.lineHeight=size*1.2;l.color=new Color(color);l.horizontalAlign=Label.HorizontalAlign.CENTER;l.verticalAlign=Label.VerticalAlign.CENTER;l.overflow=Label.Overflow.SHRINK;return n;};
  // Reuse the game's pixel wordmark and coin motif as the brand lockup.
  const logo=node('In My Pocket brand',0,h/2-44,w-56,34);const brand=logo.addComponent(Label);if(font)brand.font=font;brand.string='인마이포켓';brand.fontSize=27;brand.color=new Color('#fff0c7');brand.horizontalAlign=Label.HorizontalAlign.CENTER;brand.verticalAlign=Label.VerticalAlign.CENTER;
  const coin=node('Brand coin',-116,h/2-44,30,30);uiIcon(coin.addComponent(Graphics),'coin',27);
  rect('Brand divider',0,h/2-74,w-58,2,'#7b6d83');
  label('Feature title',mode==='entry'?'FREE SPINS':'FREE SPINS COMPLETE',h/2-106,24,accent);
  label('Free spins amount',mode==='entry'?count+'회 지급':payout.toLocaleString()+' 코인',12,mode==='entry'?46:42,'#fff2ce');
  label('Free spins detail',mode==='entry'?title:count+'회 플레이 · 프리스핀 총 당첨금',-48,20,'#bfe6df');
  const button=rect('Continue free spins',0,-h/2+45,w-64,48,mode==='entry'?'#86d5bf':'#efc675');label('Continue label',mode==='entry'?'시작':'확인',-h/2+45,24,'#242a39');button.on(Node.EventType.TOUCH_END,(event:any)=>{event.propagationStopped=true;onContinue();});
  for(const side of [-1,1])for(let i=0;i<3;i++)rect('Pixel sparkle',side*(w/2-26),50-i*44,6,6,i%2?'#c9a2ed':accent);
  panel.setScale(.97,.97,1);tween(panel).to(.22,{scale:new Vec3(1,1,1)},{easing:'backOut'}).start();
 }
 close(){this.root.removeFromParent();this.root.destroy();}
}
